def _items(state: Mapping[str, Any], key: str) -> list[dict[str, Any]]:
    value = state.get(key)
    return [dict(item) for item in value if isinstance(item, Mapping)] if isinstance(value, list) else []


def _seq(row: Mapping[str, Any] | None) -> int:
    try:
        return int((row or {}).get("seq", -1))
    except (TypeError, ValueError):
        return -1


def _summary(row: Mapping[str, Any] | None) -> dict[str, Any]:
    if not row:
        return {}
    keys = {
        "seq", "type", "timestamp", "postId", "authorHandle", "active", "text",
        "topic", "query", "view", "handle", "total", "id", "outbound", "createdAt",
    }
    return {key: row.get(key) for key in keys if key in row}


def _first_matching_post(posts: list[dict[str, Any]], query: str) -> dict[str, Any] | None:
    needle = query.strip().casefold()
    for post in posts:
        author = post.get("author") if isinstance(post.get("author"), Mapping) else {}
        haystack = " ".join(
            str(value or "")
            for value in (post.get("text"), post.get("topic"), author.get("displayName"), author.get("handle"))
        ).casefold()
        if needle in haystack:
            return post
    return None


